#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

#define MAX_TERMS 200          /* one more than the allowed 199 */
#define OUT_OF_RANGE_LIMIT 100000L

/* Helper: floor division for signed long values.
 * Returns q = floor(n/d) and sets *r = n - q*d (the remainder, always >= 0).
 */
static long floor_div(long n, long d, long *r)
{
    long q = n / d;          /* truncates toward 0 */
    long rem = n % d;        /* same sign as n */

    if (rem != 0 && ((rem < 0) != (d < 0))) {
        q -= 1;
        rem = n - q * d;
    }
    if (r) *r = rem;
    return q;
}

int main(int argc, char *argv[])
{
    if (argc < 3) {
        puts("NO_INPUT");
        return 0;
    }

    char *end1, *end2;
    long num = strtol(argv[1], &end1, 10);
    long den = strtol(argv[2], &end2, 10);

    if (*end1 != '\0' || *end2 != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    if (den == 0) {
        puts("ERROR");
        return 0;
    }

    if (llabs(num) > OUT_OF_RANGE_LIMIT) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    if (den < 0) {
        den = -den;
        num = -num;
    }

    long terms[MAX_TERMS];
    int count = 0;
    long n = num;
    long d = den;

    while (d != 0 && count < MAX_TERMS) {
        long r;
        long q = floor_div(n, d, &r);
        terms[count++] = q;
        n = d;
        d = r;
    }

    if (d != 0) {
        puts("ERROR");
        return 0;
    }

    putchar('[');
    if (count > 0) {
        printf("%ld", terms[0]);
        if (count > 1) {
            printf("; ");
            for (int i = 1; i < count; ++i) {
                printf("%ld", terms[i]);
                if (i + 1 < count)
                    printf(", ");
            }
        }
    }
    puts("]");
    return 0;
}
